<style>
.exp-head,.exp-tabs,.exp-actions,.exp-filters{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:20px}.exp-head{justify-content:space-between}.exp-head h1{margin:0}.exp-muted{color:#64748b;font-size:13px}.exp-btn{display:inline-flex;align-items:center;gap:6px;border:1px solid #cbd5e1;border-radius:8px;padding:10px 16px;background:#fff;color:var(--green,#1f3a5f);text-decoration:none;cursor:pointer;font:inherit}.exp-btn.primary,.exp-tabs .active{background:var(--green,#1f3a5f);color:#fff}.exp-card{background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:20px;margin-bottom:20px}.exp-table-wrap{overflow:auto}.exp-table{width:100%;border-collapse:collapse;font-size:13px}.exp-table th,.exp-table td{padding:12px;text-align:left;border-bottom:1px solid #e2e8f0;vertical-align:top}.exp-table th{white-space:nowrap;background:#f8fafc}.exp-number{white-space:nowrap}.exp-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.exp-field{display:flex;flex-direction:column;gap:6px;font-size:13px}.exp-field input,.exp-field select,.exp-field textarea,.exp-filters input{box-sizing:border-box;width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:7px;background:#fff;color:inherit;font:inherit}.exp-field.wide{grid-column:1/-1}.exp-message{padding:14px;border-radius:8px;background:#ecfdf5;color:#166534;margin-bottom:16px}.exp-message.error{background:#fef2f2;color:#991b1b}.exp-badge{display:inline-block;padding:4px 8px;background:#eef2ff;border-radius:6px;white-space:nowrap}.exp-scan-status{white-space:pre-wrap;font-size:13px;color:#475569}fieldset{min-width:0}fieldset[disabled]{opacity:.8} @media(max-width:850px){.exp-grid{grid-template-columns:1fr}.exp-head{align-items:flex-start}.exp-btn{justify-content:center}}
</style>
<style>
#main,.content-area{min-width:0}.exp-card{box-sizing:border-box;max-width:100%}.exp-table-wrap{padding:0;width:100%;max-width:100%;overflow-x:auto}.exp-table{table-layout:fixed;font-size:12px}.exp-table th,.exp-table td{padding:9px 6px;overflow-wrap:anywhere;white-space:normal}.exp-table .exp-number{font-variant-numeric:tabular-nums;white-space:normal}.exp-table .exp-btn{padding:5px;font-size:11px;max-width:100%;box-sizing:border-box}.exp-table th:first-child{width:38px}.exp-table th:last-child{width:66px}.exp-table .exp-extra-col{display:none}.exp-show-extra .exp-extra-col{display:table-cell}.exp-show-extra .exp-table{min-width:1400px}.exp-table .exp-badge{white-space:normal}.exp-filters{align-items:flex-end}.exp-filters>label:not(.exp-columns){display:flex;flex-direction:column;gap:6px}.exp-filters>label:nth-of-type(2){flex:1;min-width:180px}.exp-filters .exp-btn{height:42px;box-sizing:border-box}.exp-columns{display:flex;align-items:center;gap:6px;min-height:42px;font-size:13px}.exp-columns input{width:auto}.exp-field[hidden]{display:none}.exp-table .app-table-sort{white-space:normal;overflow-wrap:anywhere;text-align:left}.exp-grid small{color:#64748b;font-size:12px}@media(max-width:900px){.exp-table{min-width:850px}.exp-filters .exp-btn{padding:8px 12px}}
</style>
